                if self.atomic:
                    self._f = _AtomicFile(self.name, self.mode, self.encoding, self.errors)
                elif _is_binary(self.mode):
                    self._f = open(self.name, self.mode)
                else:
                    self._f = open(self.name, self.mode, encoding=self.encoding, errors=self.errors)
