    def __iter__(self):
        return iter(self._open())

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        self.close()

    @property
    def closed(self):
        return self._closed or (self._f is not None and self._f.closed)

    def close(self):
        if self._f is not None and not self._closed:
            self._f.close()
        self._closed = True


