"""Built-in parameter types and type conversion."""

import datetime as _dt
import enum
import os
import pathlib
import uuid

from ._files import _is_writing
from .exceptions import BadParameter, FileError
from .shell_completion import CompletionItem


class ParamType:
    """Base class for parameter types. Subclasses implement :meth:`convert`."""

    name = "text"
    envvar_list_splitter = None

    def convert(self, value, param, ctx):
        return value

    def get_metavar(self, param):
        return None

    def split_envvar_value(self, rv):
        return rv.split()

    def fail(self, message, param=None, ctx=None):
        raise BadParameter(message, ctx=ctx, param=param)

    def shell_complete(self, ctx, param, incomplete):
        return []

    def __call__(self, value, param=None, ctx=None):
        return self.convert(value, param, ctx)

    def __repr__(self):
        return f"<{type(self).__name__} {self.name}>"


class StringParamType(ParamType):
    name = "text"

    def convert(self, value, param, ctx):
        if isinstance(value, bytes):
            return value.decode("utf-8", "replace")
        if isinstance(value, str):
            return value
        return str(value)


class UnprocessedParamType(ParamType):
    name = "text"

    def convert(self, value, param, ctx):
        return value


class IntParamType(ParamType):
    name = "integer"

    def convert(self, value, param, ctx):
        if isinstance(value, bool):
            return int(value)
        if isinstance(value, int):
            return value
        try:
            return int(str(value).strip(), 10)
        except (TypeError, ValueError):
            self.fail(f"{value!r} is not a valid integer.", param, ctx)


class FloatParamType(ParamType):
    name = "float"

    def convert(self, value, param, ctx):
        if isinstance(value, float):
            return value
        if isinstance(value, int) and not isinstance(value, bool):
            return float(value)
        try:
            return float(str(value).strip())
        except (TypeError, ValueError):
            self.fail(f"{value!r} is not a valid floating point value.", param, ctx)


_TRUE = {"1", "true", "t", "yes", "y", "on"}
_FALSE = {"0", "false", "f", "no", "n", "off"}


class BoolParamType(ParamType):
    name = "boolean"

    def convert(self, value, param, ctx):
        if isinstance(value, bool):
            return value
        lowered = str(value).strip().lower()
        if lowered in _TRUE:
            return True
        if lowered in _FALSE:
            return False
        self.fail(f"{value!r} is not a valid boolean.", param, ctx)


class UUIDParamType(ParamType):
    name = "uuid"

    def convert(self, value, param, ctx):
        if isinstance(value, uuid.UUID):
            return value
        try:
            return uuid.UUID(str(value).strip())
        except (TypeError, ValueError):
            self.fail(f"{value!r} is not a valid UUID value.", param, ctx)


class FuncParamType(ParamType):
    """Adapts a plain conversion function that raises ``ValueError`` on refusal."""

    def __init__(self, func):
        self.func = func
        self.name = getattr(func, "__name__", "text") or "text"

    def convert(self, value, param, ctx):
        if not isinstance(value, str):
            return value
        try:
            return self.func(value)
        except BadParameter:
            raise
        except ValueError as e:
            self.fail(str(e) or f"{value!r} is not valid.", param, ctx)


class Choice(ParamType):
    """A closed list of allowed values, or the members of an enumeration."""

    name = "choice"

    def __init__(self, choices, case_sensitive=True):
        if isinstance(choices, type) and issubclass(choices, enum.Enum):
            self.choices = list(choices)
            self.keys = [member.name for member in self.choices]
        else:
            self.choices = list(choices)
            self.keys = [str(choice) for choice in self.choices]
        self.case_sensitive = case_sensitive

    def get_metavar(self, param):
        return "[" + "|".join(self.keys) + "]"

    def _norm(self, text, ctx):
        func = getattr(ctx, "token_normalize_func", None) if ctx is not None else None
        if func is not None:
            text = func(text)
        if not self.case_sensitive:
            text = text.casefold()
        return text

    def convert(self, value, param, ctx):
        for choice in self.choices:
            if choice is value:
                return choice
        text = value if isinstance(value, str) else str(value)
        wanted = self._norm(text, ctx)
        for key, choice in zip(self.keys, self.choices):
            if self._norm(key, ctx) == wanted:
                return choice
        shown = ", ".join(repr(k) for k in self.keys)
        self.fail(f"{text!r} is not {shown}.", param, ctx)

    def shell_complete(self, ctx, param, incomplete):
        return [CompletionItem(key) for key in self.keys if key.startswith(incomplete)]


_DEFAULT_DATETIME_FORMATS = ["%Y-%m-%d", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"]


class DateTime(ParamType):
    name = "datetime"

    def __init__(self, formats=None):
        self.formats = list(formats) if formats is not None else list(_DEFAULT_DATETIME_FORMATS)

    def convert(self, value, param, ctx):
        if isinstance(value, _dt.datetime):
            return value
        for fmt in self.formats:
            try:
                return _dt.datetime.strptime(str(value), fmt)
            except ValueError:
                continue
        shown = ", ".join(repr(f) for f in self.formats)
        self.fail(f"{value!r} does not match the formats {shown}.", param, ctx)


def _range_desc(lo, hi, lo_open, hi_open):
    left = "(" if lo_open else "["
    right = ")" if hi_open else "]"
