def pass_context(func):
    """Pass the current :class:`Context` as the first argument."""

    def new_func(*args, **kwargs):
        return func(get_current_context(), *args, **kwargs)

    return update_wrapper(new_func, func)


def pass_obj(func):
    """Pass the current context's author object as the first argument."""

    def new_func(*args, **kwargs):
        return func(get_current_context().obj, *args, **kwargs)

    return update_wrapper(new_func, func)


