import contextlib
import io
import os
import shutil
import shlex
import sys
import tempfile


class _Sink(io.BytesIO):
    """A byte sink that also appends every write to a shared, ordered buffer."""

    def __init__(self, shared):
        super().__init__()
        self._shared = shared

    def write(self, data):
        self._shared.write(data)
        return super().write(data)


