import optlyn
from optlyn import command, group, option, argument, pass_context, Choice, IntRange
from optlyn.testing import CliRunner

@command()
@option("--count", "-c", type=int, default=1, help="How many.")
@option("--shout/--quiet", default=False)
@argument("name")
def hello(count, shout, name):
    """Say hello.

    Long description here.
    """
    msg = f"Hello {name} x{count}"
    print(msg.upper() if shout else msg)

@group()
@option("--debug", is_flag=True)
def cli(debug):
    """Top group."""
    print("debug", debug)

@cli.command("sub")
@option("--n", type=IntRange(0, 10), default=3)
def sub_cmd(n):
    print("sub", n)

cli.add_command(hello)

r = CliRunner()
for args in [["hello", "bob"], ["hello", "-c", "3", "--shout", "bob"], ["--debug", "sub", "--n", "5"],
             ["hello", "--help"], ["sub", "--n", "99"], ["hello"], [], ["--help"], ["nope"], ["sub", "--help"]]:
    res = r.invoke(cli, args)
    print("ARGS", args, "EXIT", res.exit_code)
    print(res.output)
    if res.exception and not isinstance(res.exception, SystemExit):
        print("EXC", repr(res.exception))
