    col = min(max(len(first) for first, _ in rows), 28)
    help_indent = " " * (col + 4)
    body_width = max(width - len(help_indent), 20)
    out = []
    for first, text in rows:
        if not text:
            out.append(f"  {first}")
            continue
        body = wrap_text(text, body_width).split("\n")
        if len(first) > col:
            out.append(f"  {first}")
            out.extend(help_indent + line for line in body)
        else:
            out.append(f"  {first.ljust(col)}  {body[0]}")
            out.extend(help_indent + line for line in body[1:])
    return out

